# German texts for the six legendary Spirlings (Hallowmur, Scriptorax, Lumivane, Zephyrel,
# Monolurk, Vorlucent): Spirlog entries, meeting lines and the retreat line.
KEEP = ["Hallowmur", "Scriptorax", "Lumivane", "Zephyrel", "Monolurk", "Vorlucent"]
